	@Test
	void recordIteratorKeepsPositionWhenCurrentQuadSurvivesAndRowsAreInsertedAroundIt(@TempDir Path dataDir)
			throws Exception {
		long[] first = { 20, 5, 200, 1 };
		long[] last = { 40, 5, 400, 1 };
		long[] insertedBefore = { 10, 5, 100, 1 };
		long[] insertedAfter = { 30, 5, 300, 1 };

		try (TripleStore store = openStore(dataDir)) {
			write(store, () -> {
				store.storeTriple(first[0], first[1], first[2], first[3], true);
				store.storeTriple(last[0], last[1], last[2], last[3], true);
			});

			try (Txn reader = store.getTxnManager().createReadTxn();
					RecordIterator records = store.getTriples(reader, -1, -1, -1, -1, true)) {
				assertArrayEquals(first, records.next());
				long versionBeforeCommit = reader.version();
				write(store, () -> {
					store.storeTriple(insertedBefore[0], insertedBefore[1], insertedBefore[2], insertedBefore[3], true);
					store.storeTriple(insertedAfter[0], insertedAfter[1], insertedAfter[2], insertedAfter[3], true);
				});

				assertNotEquals(versionBeforeCommit, reader.version());
				assertRows(List.of(insertedAfter, last), readRecords(records));
			}
		}
	}

