	@Test
	void contextIteratorKeepsPositionWhenCurrentContextSurvivesAndContextsAreInsertedAroundIt(@TempDir Path dataDir)
			throws Exception {
		long[] initialContexts = { 20, 40 };

		try (TripleStore store = openStore(dataDir)) {
			write(store, () -> {
				for (int i = 0; i < initialContexts.length; i++) {
					store.storeTriple(100 + i, 5, 200 + i, initialContexts[i], true);
				}
			});

			try (Txn reader = store.getTxnManager().createReadTxn();
					LmdbContextIdIterator contexts = store.getContexts(reader)) {
				assertEquals(initialContexts[0], contexts.next()[0]);
				write(store, () -> {
					store.storeTriple(110, 5, 210, 10, true);
					store.storeTriple(130, 5, 230, 30, true);
				});

				List<Long> actual = new ArrayList<>();
				long[] next;
				while ((next = contexts.next()) != null) {
					actual.add(next[0]);
				}
				assertEquals(List.of(30L, 40L), actual);
			}
		}
	}

	private static TripleStore openStore(Path dataDir) throws IOException {
		return new TripleStore(dataDir.toFile(), new LmdbStoreConfig("cspo,spoc").setAutoGrow(false), null);
	}

	private static void write(TripleStore store, Mutation mutation) throws Exception {
		store.startTransaction();
		try {
			mutation.apply();
			store.commit();
		} catch (Exception | Error failure) {
			try {
				store.rollback();
			} catch (Exception | Error rollbackFailure) {
				failure.addSuppressed(rollbackFailure);
			}
			throw failure;
		}
	}

	private static List<long[]> readRecords(RecordIterator iterator) {
		List<long[]> rows = new ArrayList<>();
		long[] row;
		while ((row = iterator.next()) != null) {
			rows.add(row.clone());
		}
		return rows;
	}

	private static void assertRows(List<long[]> expected, List<long[]> actual) {
		assertEquals(expected.size(), actual.size(), "iterator must return the exact expected number of rows");
		for (int i = 0; i < expected.size(); i++) {
			assertArrayEquals(expected.get(i), actual.get(i), "unexpected row at iterator position " + i);
		}
	}

	@FunctionalInterface
	private interface Mutation {
		void apply() throws Exception;
	}
